CREATE TABLE cmdb_ire_observations (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY, tenant_id BIGINT UNSIGNED NOT NULL, run_id BIGINT UNSIGNED NOT NULL, source_row INT UNSIGNED NOT NULL, scope_key VARCHAR(255) NOT NULL DEFAULT '', source_native_key VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_as_cs NOT NULL, parent_ci_id BIGINT UNSIGNED NULL, observed_at DATETIME(6) NOT NULL, values_json JSON NOT NULL, result_state ENUM('PENDING','MATCH','NEW','INSUFFICIENT','CONFLICT','MULTIPLE','APPLIED','REJECTED') NOT NULL DEFAULT 'PENDING', ci_id BIGINT UNSIGNED NULL, rule_version BIGINT UNSIGNED NOT NULL DEFAULT 0, candidates JSON NOT NULL, accepted_changes JSON NOT NULL, rejected_changes JSON NOT NULL, reason_code VARCHAR(80) NOT NULL DEFAULT '', reason_message VARCHAR(500) NOT NULL DEFAULT '', processed_at DATETIME(6) NULL, UNIQUE KEY cmdb_ire_observation_row(tenant_id,run_id,source_row), KEY cmdb_ire_observation_state(tenant_id,run_id,result_state,source_row), KEY cmdb_ire_observation_identity(tenant_id,scope_key,source_native_key), CONSTRAINT cmdb_ire_observation_run FOREIGN KEY(tenant_id,run_id) REFERENCES cmdb_ire_runs(tenant_id,id) ON DELETE CASCADE, CONSTRAINT cmdb_ire_observation_parent FOREIGN KEY(tenant_id,parent_ci_id) REFERENCES cmdb_cis(tenant_id,id), CONSTRAINT cmdb_ire_observation_ci FOREIGN KEY(tenant_id,ci_id) REFERENCES cmdb_cis(tenant_id,id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
